#!/usr/bin/env node
/**
 * Generates the legacy Nitro bindings into `nitrogen/generated-legacy`.
 *
 * Nitro 0.35 changed how Android hybrid objects are built on fbjni, so code
 * generated by nitrogen >= 0.35 only compiles against react-native-nitro-modules
 * >= 0.35, and code from nitrogen 0.34 only against 0.32 – 0.34. To support
 * both, the package ships both trees; android/build.gradle and the podspec
 * pick one from the app's installed react-native-nitro-modules version
 * (see nitro-compat.json, android/build.gradle and RsNativeKitSecurity.podspec).
 *
 * nitrogen hardcodes `nitrogen/generated/` in the build glue it emits
 * (autolinking .gradle/.cmake/.rb), so those paths are rewritten afterwards.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = 'nitrogen/generated-legacy';
const require = createRequire(join(root, 'package.json'));

const legacyPackage = require.resolve('nitrogen-legacy/package.json');
const { version, bin } = JSON.parse(readFileSync(legacyPackage, 'utf8'));
const entry = join(dirname(legacyPackage), typeof bin === 'string' ? bin : bin.nitrogen);

rmSync(join(root, outDir), { recursive: true, force: true });
console.log(`[nitrogen-legacy] generating ${outDir} with nitrogen ${version}`);
execFileSync(process.execPath, [entry, '--out', `./${outDir}`], { cwd: root, stdio: 'inherit' });

const glue = /\+autolinking\.(gradle|cmake|rb)$/;
function rewrite(dir) {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) {
      rewrite(path);
    } else if (glue.test(name)) {
      const before = readFileSync(path, 'utf8');
      const after = before.replaceAll('nitrogen/generated/', `${outDir}/`);
      if (after.includes('nitrogen/generated/')) {
        throw new Error(`[nitrogen-legacy] unrewritten path in ${path}`);
      }
      if (after !== before) writeFileSync(path, after);
    }
  }
}
rewrite(join(root, outDir));
console.log('[nitrogen-legacy] done');
